// JSX in a TypeScript package: elements, fragments, spreads, entities, nesting.
import { Icon } from "./icon";

type CardProps = { title: string; items: string[]; extra?: Record<string, string> };

export function Card({ title, items, extra }: CardProps) {
  return (
    <section className="card" data-kind="list" {...extra}>
      <h1>{title} &amp; more</h1>
      {/* a comment child */}
      <Icon.Star size={2} filled />
      <ul>
        {items.map((it) => <li key={it}>{it}</li>)}
      </ul>
      <>
        don't   wrap
        lines
      </>
    </section>
  );
}

export const generic = <T,>(x: T): T => x;
export const tag = (n: number) => (n > 1 ? <b>many</b> : <i>one</i>);
